PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE "anomaly_scenarios" ("scenario_id" TEXT, "issue_type" TEXT, "operation_id" TEXT, "related_operation_id" TEXT, "machine_id" TEXT, "proposed_start" TEXT, "proposed_end" TEXT, "proposed_setup_minutes" TEXT, "expected_detection" TEXT, "description" TEXT, "evidence" TEXT, PRIMARY KEY("scenario_id"), FOREIGN KEY("operation_id") REFERENCES "operations"("operation_id"), FOREIGN KEY("related_operation_id") REFERENCES "operations"("operation_id"), FOREIGN KEY("machine_id") REFERENCES "machines"("machine_id"));
CREATE TABLE "audit_events" ("event_id" TEXT, "entity_type" TEXT, "entity_id" TEXT, "event_type" TEXT, "actor" TEXT, "payload" TEXT, "occurred_at" TEXT, PRIMARY KEY("event_id"));
CREATE TABLE "changeover_matrix" ("changeover_id" TEXT, "machine_id" TEXT, "from_setup" TEXT, "to_setup" TEXT, "changeover_minutes" NUMERIC, "effective_from" TEXT, "effective_to" TEXT, PRIMARY KEY("changeover_id"), FOREIGN KEY("machine_id") REFERENCES "machines"("machine_id"));
CREATE TABLE "ground_truth" ("scenario_id" TEXT, "operation_id" TEXT, "issue_type" TEXT, "ground_truth" TEXT, "expected_detection" TEXT, "description" TEXT, PRIMARY KEY("scenario_id"), FOREIGN KEY("operation_id") REFERENCES "operations"("operation_id"));
CREATE TABLE "inventory_lots" ("lot_id" TEXT, "material_id" TEXT, "lot_number" TEXT, "quantity" NUMERIC, "available_from" TEXT, "expiry_date" TEXT, "quality_status" TEXT, PRIMARY KEY("lot_id"), FOREIGN KEY("material_id") REFERENCES "materials"("material_id"));
CREATE TABLE "labor_shifts" ("weekday" NUMERIC, "shift_start" TEXT, "shift_end" TEXT, "workers_available" NUMERIC, "effective_from" TEXT, "effective_to" TEXT, PRIMARY KEY("weekday","shift_start","effective_from"));
CREATE TABLE "machine_calendars" ("machine_id" TEXT, "weekday" NUMERIC, "shift_start" TEXT, "shift_end" TEXT, "capacity_minutes" NUMERIC, "effective_from" TEXT, "effective_to" TEXT, PRIMARY KEY("machine_id","weekday","shift_start","effective_from"), FOREIGN KEY("machine_id") REFERENCES "machines"("machine_id"));
CREATE TABLE "machine_downtime" ("downtime_id" TEXT, "machine_id" TEXT, "start_at" TEXT, "end_at" TEXT, "reason" TEXT, "issue_type" TEXT, PRIMARY KEY("downtime_id"), FOREIGN KEY("machine_id") REFERENCES "machines"("machine_id"));
CREATE TABLE "machine_tooling" ("machine_id" TEXT, "tooling_id" TEXT, PRIMARY KEY("machine_id","tooling_id"), FOREIGN KEY("machine_id") REFERENCES "machines"("machine_id"), FOREIGN KEY("tooling_id") REFERENCES "tooling"("tooling_id"));
CREATE TABLE "machines" ("machine_id" TEXT, "name" TEXT, "machine_type" TEXT, "capacity_units_per_hour" NUMERIC, "location" TEXT, "lifecycle_state" TEXT, "available_from" TEXT, "available_to" TEXT, PRIMARY KEY("machine_id"));
CREATE TABLE "material_reservations" ("reservation_id" TEXT, "run_id" TEXT, "order_id" TEXT, "material_id" TEXT, "lot_id" TEXT, "quantity" NUMERIC, "reserved_at" TEXT, FOREIGN KEY("run_id") REFERENCES "scheduling_runs"("run_id"), FOREIGN KEY("order_id") REFERENCES "production_orders"("order_id"), FOREIGN KEY("material_id") REFERENCES "materials"("material_id"), FOREIGN KEY("lot_id") REFERENCES "inventory_lots"("lot_id"));
CREATE TABLE "materials" ("material_id" TEXT, "name" TEXT, "category" TEXT, "unit" TEXT, "lifecycle_state" TEXT, PRIMARY KEY("material_id"));
CREATE TABLE "operation_eligible_machine" ("operation_id" TEXT, "machine_id" TEXT, PRIMARY KEY("operation_id","machine_id"), FOREIGN KEY("operation_id") REFERENCES "operations"("operation_id"), FOREIGN KEY("machine_id") REFERENCES "machines"("machine_id"));
CREATE TABLE "operation_schedules" ("schedule_id" TEXT, "run_id" TEXT, "operation_id" TEXT, "machine_id" TEXT, "start_at" TEXT, "end_at" TEXT, "setup_minutes" NUMERIC, "processing_minutes" NUMERIC, "decision_reason" TEXT, "created_at" TEXT, PRIMARY KEY("schedule_id"), FOREIGN KEY("run_id") REFERENCES "scheduling_runs"("run_id"), FOREIGN KEY("operation_id") REFERENCES "operations"("operation_id"), FOREIGN KEY("machine_id") REFERENCES "machines"("machine_id"));
CREATE TABLE "operations" ("operation_id" TEXT, "order_id" TEXT, "routing_step_id" TEXT, "sequence_no" NUMERIC, "duration_minutes" NUMERIC, "required_workers" NUMERIC, "status" TEXT, PRIMARY KEY("operation_id"), FOREIGN KEY("order_id") REFERENCES "production_orders"("order_id"), FOREIGN KEY("routing_step_id") REFERENCES "routing_steps"("step_id"));
CREATE TABLE "product_material" ("product_id" TEXT, "material_id" TEXT, "quantity_per_unit" NUMERIC, PRIMARY KEY("product_id","material_id"), FOREIGN KEY("product_id") REFERENCES "products"("product_id"), FOREIGN KEY("material_id") REFERENCES "materials"("material_id"));
CREATE TABLE "production_orders" ("order_id" TEXT, "product_id" TEXT, "routing_id" TEXT, "quantity" NUMERIC, "order_date" TEXT, "due_date" TEXT, "priority" NUMERIC, "status" TEXT, "created_at" TEXT, PRIMARY KEY("order_id"), FOREIGN KEY("product_id") REFERENCES "products"("product_id"), FOREIGN KEY("routing_id") REFERENCES "routings"("routing_id"));
CREATE TABLE "products" ("product_id" TEXT, "sku_code" TEXT, "name" TEXT, "category" TEXT, "unit" TEXT, "lifecycle_state" TEXT, "created_at" TEXT, PRIMARY KEY("product_id"));
CREATE TABLE "routing_step_machines" ("routing_step_id" TEXT, "machine_id" TEXT, PRIMARY KEY("routing_step_id","machine_id"), FOREIGN KEY("routing_step_id") REFERENCES "routing_steps"("step_id"), FOREIGN KEY("machine_id") REFERENCES "machines"("machine_id"));
CREATE TABLE "routing_steps" ("step_id" TEXT, "routing_id" TEXT, "sequence_no" NUMERIC, "name" TEXT, "base_minutes_per_unit" NUMERIC, "required_workers" NUMERIC, "tooling_id" TEXT, "machine_type_required" TEXT, "setup_family" TEXT, PRIMARY KEY("step_id"), FOREIGN KEY("routing_id") REFERENCES "routings"("routing_id"), FOREIGN KEY("tooling_id") REFERENCES "tooling"("tooling_id"));
CREATE TABLE "routings" ("routing_id" TEXT, "product_id" TEXT, "version" NUMERIC, "effective_from" TEXT, "effective_to" TEXT, "lifecycle_state" TEXT, "created_at" TEXT, PRIMARY KEY("routing_id"), FOREIGN KEY("product_id") REFERENCES "products"("product_id"));
CREATE TABLE "schedule_exceptions" ("id" TEXT, "run_id" TEXT, "operation_id" TEXT, "issue_type" TEXT, "severity" TEXT, "message" TEXT, "details" TEXT, "detected_at" TEXT, PRIMARY KEY("id"), FOREIGN KEY("run_id") REFERENCES "scheduling_runs"("run_id"), FOREIGN KEY("operation_id") REFERENCES "operations"("operation_id"));
CREATE TABLE "scheduling_runs" ("run_id" TEXT, "strategy" TEXT, "seed" TEXT, "status" TEXT, "planning_start" TEXT, "created_at" TEXT, "completed_at" TEXT, "metrics" TEXT, PRIMARY KEY("run_id"));
CREATE TABLE "tooling" ("tooling_id" TEXT, "name" TEXT, "capacity" NUMERIC, "lifecycle_state" TEXT, PRIMARY KEY("tooling_id"));
COMMIT;
PRAGMA foreign_keys=ON;
